#!/usr/bin/env bash
# Linux compat entry for scripts/45-bootstrap-gradle.ps1
# Same core logic: download the pinned Gradle distribution, verify its SHA-256,
# and generate the fixture Gradle wrapper.
#
# Minimal fix vs. the .ps1 stage: the wrapper is generated by the Linux `gradle`
# launcher (the .ps1 stage runs gradle.bat).
set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
FIXTURE="$ROOT/fixture"

GRADLE_VERSION="$(python3 -c 'import json;print(json.load(open("'"$ROOT"'/versions.json"))["gradle"]["version"])')"
ZIP_URL="$(python3 -c 'import json;print(json.load(open("'"$ROOT"'/versions.json"))["gradle"]["distributionUrl"])')"
EXPECTED_SHA="$(python3 -c 'import json;print(json.load(open("'"$ROOT"'/versions.json"))["gradle"]["sha256"])')"

if [ -f "$FIXTURE/gradlew" ]; then
    echo "[OK] Gradle wrapper already exists."
    exit 0
fi

CACHE="$ROOT/.cache"
mkdir -p "$CACHE"
ZIP="$CACHE/gradle-$GRADLE_VERSION-bin.zip"
UNPACK="$CACHE/gradle-$GRADLE_VERSION"

if [ ! -f "$ZIP" ]; then
    echo "[Gradle] downloading $ZIP_URL"
    curl -fL --retry 5 --retry-delay 3 -o "$ZIP" "$ZIP_URL"
fi

ACTUAL_SHA="$(sha256sum "$ZIP" | awk '{print $1}')"
if [ "$ACTUAL_SHA" != "$EXPECTED_SHA" ]; then
    echo "ERROR: Gradle ZIP checksum mismatch. Expected $EXPECTED_SHA, got $ACTUAL_SHA" >&2
    exit 1
fi
echo "[OK] Gradle distribution SHA-256 verified."

if [ ! -d "$UNPACK" ]; then
    ( cd "$CACHE" && unzip -q -o "$ZIP" )
fi

GRADLE_BIN="$UNPACK/bin/gradle"
if [ ! -x "$GRADLE_BIN" ]; then
    echo "ERROR: cannot find $GRADLE_BIN" >&2
    exit 1
fi

"$GRADLE_BIN" -p "$FIXTURE" wrapper --gradle-version "$GRADLE_VERSION" --distribution-type bin
echo "[OK] Gradle wrapper generated."
echo "GRADLE-WRAPPER: PASS"
